from exlib import *
import sys
H = int(sys.argv[1]) if len(sys.argv) > 1 else 1800
b = Board('Explainer_Rules', 'Rules', 1280, H, hdr=False)
css = '''<style>.rc{background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;box-sizing:border-box}.rc h2{font-size:16px;font-weight:800}.rc li{font-size:13px;line-height:20px;color:#334155;margin-bottom:6px}.rc ul{padding-left:18px;margin:0}.mono{font-family:'JetBrains Mono',monospace;font-size:12px}</style>'''
def card(t, inner): return f'<div class="rc"><h2>{t}</h2>{inner}</div>'
def ul(*it): return '<ul>' + ''.join(f'<li>{i}</li>' for i in it) + '</ul>'
cards = [
 card('What it is for', ul('An explainer teaches one idea to someone outside the field: a new teammate, a customer, a manager.', 'It answers a single question in its title, and a reader gets the answer in under a minute.', 'Other diagram types record a system. An explainer tells a story about it.')),
 card('Four shapes', ul('<b>Layers:</b> a journey from top to bottom through bands (how a page reaches you).', '<b>Tree:</b> one root and a list of parts, each with a line of purpose (what is inside a project).', '<b>Comparison:</b> two things side by side, read row by row (SQL or NoSQL).', '<b>Concept:</b> one idea in the middle and four short facts around it, with an analogy below (what a cache does).')),
 card('Title and subtitle', ul('Title: 40 px, bold, written as the question or the topic: <i>What a cache does</i>. No verb in the imperative.', 'Subtitle: one or two sentences, 16 px, grey. It says what the reader will know afterwards, and how to read the picture ("follow the numbers").', 'Both sit at the top left, with 64 px margin.')),
 card('Cards', ul('Vertical card 260 × 200: an 88 px icon from the detailed set, a name pill, two lines of text. Tinted, 2 px ink border, 16 px corners.', 'Row card 700 × 92: icon 60 px on the left, a mono name, one line of text. For lists and trees.', 'Text is 12.5 px and at most 14 words. One idea per card.', 'Name the thing in the reader\'s words (<i>Your browser</i>), not in the system\'s (<i>Client</i>).')),
 card('Numbers and reading order', ul('A dark numbered badge sits on a card\'s top left corner, 1, 2, 3 in the order the story is read.', 'Layers read top to bottom, then left to right inside a band. A comparison reads row by row. A tree reads top to bottom.', 'Number only when the order matters. A tree and a comparison need none.', 'Branches that happen at the same time share a number and take a letter: 3a, 3b.')),
 card('Lines and labels', ul('The same roles as the other types, used sparingly: ink for a step, blue animated for the one path the story follows, dashed slate for a return.', 'A label says what happens in everyday words: <i>asks "where is it?"</i>, <i>no copy</i>. Never a protocol name.', 'At most two bends. Labels sit on the line with 90 px of room.')),
 card('Bands and tints', ul('A band is a wide rounded strip behind a row, with a pill label on its top left: <i>You</i>, <i>The edge</i>, <i>The data</i>.', 'One tint per band, from the shared palette. The same tint means the same kind of thing across all explainers.', 'A band is 248 px high for one row of cards and gives 40 px between cards and band edge.')),
 card('Words', ul('Plain language. Define a term the first time it appears (<i>DNS</i>: turns a name into a number).', 'Prefer an analogy to a definition. A desk and a library explain a cache better than a paragraph.', 'Keep every sentence short, active and in the present tense.', 'A closing line may give the fast path, the rule of thumb or the caveat. One line, bold, no more.')),
 card('Size and density', ul('Four to eight cards. More than eight: split into two explainers.', 'Width 1400 to 1500 px. Rows 280 to 290 px apart in layers, 112 px in a tree, 124 px in a comparison.', 'Empty space is fine. A band with one card may carry a bold remark in its free half.')),
 card('Style and animation', ul('Always illustrated. A plain version of the same content would be a flowchart or a table, so there is no second mode.', 'Animation only on the blue path, off when the viewer prefers reduced motion. In draw.io each line has its own flow animation (flowAnimation=1) and its own duration: main route 500, event stream 1500. Checked in the draw.io viewer; SVG export not yet tested.', 'No decoration that carries no meaning: no stock art, no shadows beyond the pill.')),
 card('Reading it with other types', ul('An explainer often introduces a technical diagram. The same icons and tints appear in both, so the reader recognises the parts.', 'Name the related architecture or sequence page in the subtitle or a closing line.', 'Not decided yet: whether a card can link to the page that shows it in detail.')),
 card('What a plugin can rely on', ul('A diagram is: shape (layers, tree, comparison, concept), title, subtitle and a list of cards.', 'A card is: name, text, icon, tone, optional number and optional band.', 'A link is: from, to, role and a spoken label. A comparison is: two cards and a list of rows with a label and two texts.', 'Layout comes from the shape: bands for layers, rows for trees and comparisons, a hub for concepts.', 'Anything not covered is left to the diagram author.')),
]
grid = f'<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px">{"".join(cards)}</div>'
b.raw(css + f'<div style="position:absolute;left:0;top:0;width:1280px;box-sizing:border-box;padding:64px;display:flex;flex-direction:column;gap:28px"><div style="display:flex;flex-direction:column;gap:8px"><div style="font-size:24px;font-weight:600">Explainer · Rules</div><div style="font-size:13px;line-height:20px;color:#475569;max-width:900px">The conventions every explainer follows, and that a plugin can rely on. The four examples show the four shapes: layers, tree, comparison and concept.</div></div>{grid}</div>')
print(save3(b))
